const e = $('Chamado por outro workflow').first().json;
const raw = $input.first().json || {};
const o = raw.output || null;
const falhou = !o;
const d = o || {};
const INCOTERMS = ['EXW', 'FCA', 'FAS', 'FOB', 'CFR', 'CIF', 'CPT', 'CIP', 'DAP', 'DPU', 'DDP'];
const txt = (v, n) => (v === null || v === undefined || String(v).trim() === '') ? null : String(v).trim().slice(0, n);
const quantidade = typeof d.quantidade === 'number' && d.quantidade > 0 ? d.quantidade : null;
const unidade = ['kg', 't'].includes(String(d.unidade || '').toLowerCase()) ? String(d.unidade).toLowerCase() : (quantidade ? 'kg' : null);
const incoterm = INCOTERMS.includes(String(d.incoterm || '').toUpperCase()) ? String(d.incoterm).toUpperCase() : null;
const pais = /^[A-Za-z]{2}$/.test(String(d.destino_pais || '')) ? String(d.destino_pais).toUpperCase() : null;
const conf = typeof d.confianca === 'number' ? Math.min(1, Math.max(0, d.confianca)) : 0;
const empresaExtraida = txt(d.empresa, 200);
const empresa = empresaExtraida || txt(e.remetente_nome, 200) || String(e.remetente_email || '').split('@')[1] || 'Desconhecido';
const campos = { cliente: empresaExtraida, produto: txt(d.produto, 200), densidade: txt(d.densidade, 100), granulometria: txt(d.granulometria, 100), quantidade, embalagem: txt(d.embalagem, 200), incoterm, destino_pais: pais };
const emFalta = Object.keys(campos).filter(k => campos[k] === null);
const ePedido = falhou ? true : d.e_pedido_de_proposta === true;
const en = String(d.idioma || '').toLowerCase() === 'en';
const ROT = { cliente: ['empresa', 'company'], produto: ['produto', 'product'], densidade: ['densidade', 'density'], granulometria: ['granulometria', 'granulometry'], quantidade: ['quantidade', 'quantity'], embalagem: ['embalagem', 'packaging'], incoterm: ['Incoterm', 'Incoterm'], destino_pais: ['país de destino', 'destination country'] };
const lista = emFalta.map(k => '- ' + ROT[k][en ? 1 : 0]).join('\n');
const nome = txt(d.contacto_nome, 80);
let rascunho;
if (!ePedido) rascunho = null;
else if (emFalta.length === 0) rascunho = en ? 'Hello' + (nome ? ' ' + nome : '') + ',\n\nThank you for your request. We are preparing the proposal and will get back to you shortly.\n\nKind regards' : 'Olá' + (nome ? ' ' + nome : '') + ',\n\nObrigado pelo seu pedido. Estamos a preparar a proposta e respondemos em breve.\n\nCumprimentos';
else rascunho = en ? 'Hello' + (nome ? ' ' + nome : '') + ',\n\nThank you for your request. To prepare the proposal we still need:\n' + lista + '\n\nKind regards' : 'Olá' + (nome ? ' ' + nome : '') + ',\n\nObrigado pelo seu pedido. Para prepararmos a proposta precisamos ainda de:\n' + lista + '\n\nCumprimentos';
const slack = '📧 Pedido por email (rascunho a rever): *' + empresa + '* · ' + (campos.produto || 'produto?') + ' · ' + (pais || 'país?') + ' · ' + (quantidade ? quantidade + ' ' + unidade : 'qtd?') + ' · confiança ' + conf.toFixed(2) + (emFalta.length ? ' · em falta: ' + emFalta.join(', ') : '') + (falhou ? ' · (o LLM falhou, ler o email)' : '');
return [{ json: {
  email_id: e.email_id, assunto: String(e.assunto || '').slice(0, 200), remetente_email: e.remetente_email, remetente_nome: e.remetente_nome,
  falhou_llm: falhou, e_pedido: ePedido, confianca: falhou ? 0 : conf,
  empresa, contacto_nome: txt(d.contacto_nome, 120), contacto_email: txt(d.contacto_email, 200) || e.remetente_email,
  produto: campos.produto, densidade: campos.densidade, granulometria: campos.granulometria, quantidade, unidade, embalagem: campos.embalagem, incoterm, destino_pais: pais, destino_local: txt(d.destino_local, 200),
  quantidade_texto: quantidade ? quantidade + ' ' + unidade : null,
  campos_em_falta: emFalta, campos_em_falta_texto: '{' + emFalta.join(',') + '}',
  dados_extraidos: JSON.stringify({ ...campos, destino_local: txt(d.destino_local, 200), idioma: txt(d.idioma, 10), contacto_nome: txt(d.contacto_nome, 120) }),
  rascunho_resposta: rascunho, resumo_slack: slack
} }];
